// Inputs: sheet ('real' | 'demo'), desde, hasta (yyyy-MM-dd, inclusive). Default: last full Monday-Sunday week (Arizona).
// Entradas: sheet ('real' | 'demo'), desde, hasta. Por defecto: la semana pasada completa, de lunes a domingo.
const SHEETS = {
  real: 'YOUR_GOOGLE_SHEET_ID',   // Lumière Aesthetics (production data)
  demo: 'YOUR_DEMO_GOOGLE_SHEET_ID'    // Lumière Aesthetics - Demo (datos de demostración)
};
const i = $('When Called').first().json;
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const sheet = i.sheet === 'demo' ? 'demo' : 'real';
let desde = String(i.desde || ''), hasta = String(i.hasta || '');
if (!ISO.test(desde) || !ISO.test(hasta) || desde > hasta) {
  const lastMonday = $now.setZone('America/Phoenix').startOf('week').minus({ weeks: 1 });
  desde = lastMonday.toFormat('yyyy-MM-dd');
  hasta = lastMonday.plus({ days: 6 }).toFormat('yyyy-MM-dd');
}
const ranges = ['Leads', 'Conversaciones', 'Citas', 'Seguimientos', 'Calificaciones', 'Escalamientos', 'Servicios', 'Negocio', 'ROI'];
return [{ json: { sheet, desde, hasta, ranges,
  url: `https://sheets.googleapis.com/v4/spreadsheets/${SHEETS[sheet]}/values:batchGet?` + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&') } }];

// P36d — Lumière metrics for a date range + the previous range of the same length (for "vs. last week / month").
// Métricas de Lumière para un rango de fechas + el rango anterior del mismo largo (para comparar).
// Every number comes from the Sheet (source of truth). Assumptions (minutes, $/hour, no-show base rate) come from the ROI sheet,
// so the owner can see and change how the savings are estimated. Nothing is invented here.
// Todo número sale del Sheet. Los supuestos salen de la hoja ROI: la dueña ve y cambia cómo se estima el ahorro.
const p = $('Set Params').first().json;
const vr = $input.first().json.valueRanges || [];
const toObjs = r => { const v = (r && r.values) || []; const h = v[0] || []; return v.slice(1).map(row => Object.fromEntries(h.map((k, i) => [k, row[i] === undefined ? '' : row[i]]))); };
const [leads, convs, citas, segs, cals, escs, servicios, negRows, roiRows] = p.ranges.map((_, i) => toObjs(vr[i]));
const kv = rows => Object.fromEntries(rows.map(r => [r.clave, r.valor]));
const negocio = kv(negRows), roi = kv(roiRows);
const num = (v, d) => { const n = Number(String(v).replace(',', '.')); return String(v).trim() !== '' && isFinite(n) ? n : d; };
const A = {
  valor_hora: num(roi.valor_hora_recepcion_usd, 22), min_lead: num(roi.min_responder_lead, 5), min_msg: num(roi.min_mensaje_atendido, 2),
  min_cita: num(roi.min_agendar_cita, 8), min_rec: num(roi.min_recordatorio, 3), min_toque: num(roi.min_toque_seguimiento, 3),
  no_show_base: num(roi.tasa_no_show_sin_sistema_pct, 20) / 100, ticket: num(roi.ticket_promedio_usd, 350),
  consulta: num(roi.valor_consulta_usd, 175), retainer: num(roi.retainer_mensual_usd, 0), horas_mes_antes: num(roi.horas_mes_antes, 0)
};
const tz = negocio.zona_horaria || 'America/Phoenix';
const DT = s => DateTime.fromFormat(String(s).slice(0, 19), String(s).length > 16 ? 'yyyy-MM-dd HH:mm:ss' : 'yyyy-MM-dd HH:mm', { zone: tz });

// Value of a visit: price "from" for per-session services, ROI values for consultation and per-unit/monthly services
// Valor de una visita: precio "desde" en servicios por sesión; los valores de ROI para la consulta y lo que se cobra por unidad o mes
const svcBy = Object.fromEntries(servicios.map(s => [s.nombre_es, s]));
const visitValue = name => {
  const s = svcBy[name];
  if (!s) return A.ticket;
  if (s.servicio_id === 'SRV-00') return A.consulta;
  const pr = num(s.precio_desde_usd, 0);
  return ['sesión', 'tratamiento', 'jeringa'].includes(s.unidad_precio) && pr > 0 ? pr : A.ticket;
};
// Business hours by weekday (to count leads answered outside them) / horario por día (para contar leads atendidos fuera de horario)
const hrs = v => { const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/); return m ? [+m[1] * 60 + +m[2], +m[3] * 60 + +m[4]] : null; };
const H = { 1: hrs(negocio.horario_lun_vie), 2: hrs(negocio.horario_lun_vie), 3: hrs(negocio.horario_lun_vie), 4: hrs(negocio.horario_lun_vie), 5: hrs(negocio.horario_lun_vie), 6: hrs(negocio.horario_sab), 7: hrs(negocio.horario_dom) };
const outsideHours = dt => { const h = H[dt.weekday]; const m = dt.hour * 60 + dt.minute; return !h || m < h[0] || m >= h[1]; };

const segsByLead = {}; for (const s of segs) (segsByLead[s.lead_id] = segsByLead[s.lead_id] || []).push(s);
const convsByLead = {}; for (const c of convs) (convsByLead[c.lead_id] = convsByLead[c.lead_id] || []).push(c);
const remindedCita = new Set(segs.filter(s => s.origen === 'P33' && s.cita_id && !String(s.resultado).startsWith('error')).map(s => s.cita_id));
const ok = s => !String(s.resultado || '').startsWith('error');
const round = (n, d = 0) => Math.round(n * 10 ** d) / 10 ** d;

function compute(desde, hasta) {
  const inR = f => { const d = String(f || '').slice(0, 10); return d >= desde && d <= hasta; };
  const days = DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'days').days + 1;
  // Leads + first-response time (Sofía's first P31 message after the lead arrived, capped at 1 h)
  const L = leads.filter(l => inR(l.fecha_creacion));
  let fuera = 0; const resp = [];
  for (const l of L) {
    const t0 = DT(l.fecha_creacion);
    if (outsideHours(t0)) fuera++;
    const first = (convsByLead[l.lead_id] || []).find(c => c.rol === 'assistant' && c.origen === 'P31' && String(c.fecha) >= String(l.fecha_creacion));
    if (first) { const s = DT(first.fecha).diff(t0, 'seconds').seconds; if (s >= 0 && s <= 3600) resp.push(s); }
  }
  const mensajes = convs.filter(c => c.rol === 'assistant' && c.origen === 'P31' && inR(c.fecha)).length;
  // Bookings made by Sofía, and where they came from (nurturing P32 / retention P35 in the 30 days before)
  // Citas agendadas por Sofía y de dónde salieron (seguimiento P32 / retención P35 en los 30 días anteriores)
  const C = citas.filter(c => c.creada_por === 'P31' && inR(c.fecha_creacion));
  let deNurturing = 0, deRetencion = 0, valorRecuperado = 0;
  for (const c of C) {
    const created = String(c.fecha_creacion), from = DT(created).minus({ days: 30 }).toFormat('yyyy-MM-dd HH:mm:ss');
    const prev = (segsByLead[c.lead_id] || []).filter(s => String(s.fecha) < created && String(s.fecha) >= from && ok(s));
    const src = prev.some(s => s.origen === 'P35') ? 'P35' : prev.some(s => s.origen === 'P32') ? 'P32' : '';
    if (!src) continue;
    if (src === 'P35') deRetencion++; else deNurturing++;
    if (c.estado !== 'cancelada') valorRecuperado += visitValue(c.servicio);
  }
  // Visits in the range: attendance and no-shows avoided (reminded visits vs. the base no-show rate)
  // Visitas del rango: asistencia y no-shows evitados (visitas con recordatorio vs. la tasa base sin sistema)
  const V = citas.filter(c => inR(c.inicio) && ['asistio', 'no_asistio'].includes(c.estado));
  const asistio = V.filter(c => c.estado === 'asistio').length, noAsistio = V.length - asistio;
  const VR = V.filter(c => remindedCita.has(c.cita_id));
  const noShowR = VR.filter(c => c.estado === 'no_asistio').length;
  const evitados = Math.max(0, Math.round(VR.length * A.no_show_base - noShowR));
  const avgVisit = VR.length ? VR.reduce((s, c) => s + visitValue(c.servicio), 0) / VR.length : A.ticket;
  const valorNoShows = evitados * avgVisit;
  // Touches sent by each flow / toques enviados por cada flujo
  const T = { P32: 0, P33: 0, P34: 0, P35: 0 };
  for (const s of segs) if (inR(s.fecha) && ok(s) && T[s.origen] !== undefined) T[s.origen]++;
  // Ratings, reviews asked, low-rating alerts / calificaciones, reseñas pedidas, alertas
  const K = cals.filter(c => inR(c.fecha));
  const notas = K.map(c => num(c.nota, 0)).filter(n => n >= 1);
  const E = escs.filter(e => inR(e.fecha));
  // Hours the front desk did not spend / horas de recepción que nadie tuvo que gastar
  const minutos = L.length * A.min_lead + Math.max(0, mensajes - L.length) * A.min_msg + C.length * A.min_cita
    + T.P33 * A.min_rec + (T.P32 + T.P34 + T.P35) * A.min_toque;
  const horas = minutos / 60;
  const valorHoras = horas * A.valor_hora;
  const total = valorHoras + valorNoShows + valorRecuperado;
  const costo = desde.endsWith('-01') && days >= 28 && days <= 31 ? A.retainer : A.retainer * days / 30;   // full month = the retainer
  const conCita = new Set(citas.filter(c => c.creada_por === 'P31').map(c => c.lead_id));
  return {
    desde, hasta, dias: days,
    leads: L.length, leads_fuera_horario: fuera, respuesta_prom_seg: resp.length ? Math.round(resp.reduce((a, b) => a + b, 0) / resp.length) : null,
    conversion_lead_cita_pct: L.length ? round(100 * L.filter(l => conCita.has(l.lead_id)).length / L.length) : 0,
    mensajes_sofia: mensajes,
    citas_agendadas: C.length, citas_de_nurturing: deNurturing, clientas_que_vuelven: deRetencion,
    visitas: V.length, asistio, no_asistio: noAsistio, tasa_no_show_pct: V.length ? round(100 * noAsistio / V.length, 1) : 0,
    visitas_con_recordatorio: VR.length, no_shows_evitados: evitados,
    toques: T, recordatorios: T.P33,
    calificaciones: K.length, nota_promedio: notas.length ? round(notas.reduce((a, b) => a + b, 0) / notas.length, 1) : null,
    resenas_pedidas: K.filter(c => c.resultado === 'resena_pedida').length, alertas_nota_baja: K.filter(c => c.resultado === 'alerta_duena').length,
    escalamientos: E.length,
    horas_ahorradas: round(horas, 1),
    valor_horas_usd: Math.round(valorHoras), valor_no_shows_usd: Math.round(valorNoShows), valor_recuperado_usd: Math.round(valorRecuperado),
    total_usd: Math.round(total), costo_sistema_usd: Math.round(costo), roi_x: costo > 0 ? round(total / costo, 1) : null
  };
}

// Previous range: the previous calendar month for a full month (Oct vs Sep), otherwise the same number of days before
// Rango anterior: el mes calendario anterior si es un mes completo (oct vs sep); si no, los mismos días hacia atrás
const d0 = DateTime.fromISO(p.desde), d1 = DateTime.fromISO(p.hasta);
const fullMonth = d0.day === 1 && d1.hasSame(d0, 'month') && d1.day === d0.daysInMonth;
const prevHasta = fullMonth ? d0.minus({ months: 1 }).endOf('month') : d0.minus({ days: 1 });
const prevDesde = fullMonth ? d0.minus({ months: 1 }).startOf('month') : prevHasta.minus({ days: d1.diff(d0, 'days').days });
return [{ json: {
  sheet: p.sheet,
  periodo: compute(p.desde, p.hasta),
  anterior: compute(prevDesde.toFormat('yyyy-MM-dd'), prevHasta.toFormat('yyyy-MM-dd')),
  casos_abiertos: escs.filter(e => e.estado === 'abierto').length,
  supuestos: A,
  negocio: { nombre: negocio.nombre || 'Lumière Aesthetics', whatsapp_duena: negocio.whatsapp_duena || negocio.whatsapp_equipo || '',
    idioma_duena: negocio.idioma_duena || 'en', email_duena: negocio.email_duena || '', direccion: negocio.direccion || '', zona_horaria: tz, sitio_web: negocio.sitio_web || '', whatsapp_spa: negocio.whatsapp_spa || '' }
} }];
